package ru.mytv.launcher;
import android.content.pm.ResolveInfo;
import android.graphics.Rect;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;
public class TileMover {
 final MainActivity a;boolean active,releaseOK;int suppressed=-1,columns,generation;long lastMove;String selected;ArrayList<ResolveInfo> working=new ArrayList<>(),original=new ArrayList<>();ArrayList<LinearLayout> rows=new ArrayList<>();Map<String,View> tiles=new HashMap<>();
 TileMover(MainActivity a){this.a=a;}
 void bind(ArrayList<ResolveInfo> list,ArrayList<LinearLayout> gridRows,ArrayList<View> views,int cols){columns=cols;rows=new ArrayList<>(gridRows);tiles.clear();for(int i=0;i<list.size();i++){String pkg=list.get(i).activityInfo.packageName;View v=views.get(i);tiles.put(pkg,v);v.setOnLongClickListener(w->{start(pkg);return true;});}}
 void start(String pkg){if(active)return;working=HomeOptions.favorites(a,false);if(working.isEmpty()||!tiles.containsKey(pkg))return;original=HomeOptions.favorites(a,true);selected=pkg;generation++;active=true;releaseOK=true;lastMove=0;View v=tiles.get(pkg);v.cancelLongPress();v.setPressed(false);a.dialogReturn=null;a.requestedApp=v;a.resetIdle();a.hint.setText("Стрелки — переместить · OK — сохранить · Назад — отменить");focus();}
 boolean handle(KeyEvent e){int k=e.getKeyCode();if(!active){if(k==suppressed){if(e.getAction()==KeyEvent.ACTION_UP)suppressed=-1;return true;}return false;}if(k==KeyEvent.KEYCODE_VOLUME_UP||k==KeyEvent.KEYCODE_VOLUME_DOWN||k==KeyEvent.KEYCODE_VOLUME_MUTE)return false;boolean ok=k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER||k==KeyEvent.KEYCODE_NUMPAD_ENTER;if(ok){if(e.getAction()==KeyEvent.ACTION_UP)releaseOK=false;else if(e.getAction()==KeyEvent.ACTION_DOWN&&!releaseOK&&e.getRepeatCount()==0){suppressed=k;finish(true);}return true;}if(k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_ESCAPE){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){suppressed=k;finish(false);}return true;}if(e.getAction()==KeyEvent.ACTION_DOWN&&(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN)){if(e.getRepeatCount()==0||e.getEventTime()-lastMove>=140){lastMove=e.getEventTime();move(k);}}return true;}
 void move(int key){int from=-1;for(int i=0;i<working.size();i++)if(working.get(i).activityInfo.packageName.equals(selected))from=i;if(from<0)return;int to=from;if(key==KeyEvent.KEYCODE_DPAD_LEFT)to=Math.max(0,from-1);else if(key==KeyEvent.KEYCODE_DPAD_RIGHT)to=Math.min(working.size()-1,from+1);else if(key==KeyEvent.KEYCODE_DPAD_UP&&from>=columns)to=from-columns;else if(key==KeyEvent.KEYCODE_DPAD_DOWN&&from/columns<(working.size()-1)/columns)to=Math.min(working.size()-1,from+columns);if(to!=from){ResolveInfo item=working.remove(from);working.add(to,item);reflow();}}
 void reflow(){if(rows.isEmpty()||tiles.isEmpty())return;int height=tiles.values().iterator().next().getLayoutParams().height;for(LinearLayout row:rows)row.removeAllViews();int i=0;for(LinearLayout row:rows)for(int col=0;col<columns;col++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,height,1);p.setMargins(a.dp(5),a.dp(5),a.dp(5),a.dp(5));row.addView(i<working.size()?tiles.get(working.get(i).activityInfo.packageName):new View(a),p);i++;}focus();}
 void paint(){View v=tiles.get(selected);if(v==null)return;v.setScaleX(active?1.035f:1f);v.setScaleY(active?1.035f:1f);GradientDrawable bg=a.shape(active?0xff526b90:v.hasFocus()?0xff435b83:0xff242b3f);if(active)bg.setStroke(a.dp(3),0xffffd477);else if(v.hasFocus())bg.setStroke(a.dp(2),0xffd7e6ff);v.setBackground(bg);}
 void focus(){View v=tiles.get(selected);if(v==null)return;int token=generation;v.requestFocus();paint();v.post(()->{if(token==generation&&a.live()&&v.isAttachedToWindow()){v.requestFocus();v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),false);paint();}});}
 void finish(boolean save){if(!active)return;active=false;releaseOK=false;if(save){Set<String> visible=new HashSet<>();for(ResolveInfo r:working)visible.add(r.activityInfo.packageName);Iterator<ResolveInfo> ordered=working.iterator();ArrayList<ResolveInfo> result=new ArrayList<>();for(ResolveInfo r:original)result.add(visible.contains(r.activityInfo.packageName)?ordered.next():r);HomeOptions.saveOrder(a,result);}else{Set<String> hide=HomeOptions.hidden(a);working=new ArrayList<>();for(ResolveInfo r:original)if(!hide.contains(r.activityInfo.packageName))working.add(r);reflow();}a.hint.setText("OK — открыть · В избранном удерживай OK для перемещения");a.requestedApp=tiles.get(selected);focus();a.resetIdle();}
 void discard(){generation++;active=false;releaseOK=false;suppressed=-1;paint();selected=null;original.clear();working.clear();rows.clear();tiles.clear();}
}
